    'tst.46': ['{name} artık {role}.', '{name} is now {role}.'], 'tst.47': ['{name} kulüpten çıkarıldı.', '{name} was removed from the club.'], 'tst.48': ['Etkinlik iptal edildi. Katılımcılara haber verildi.', 'Event cancelled. Attendees were notified.'], 'tst.49': ['Başkanlık {name} kullanıcısına devredildi.', 'Presidency transferred to {name}.'], 'tst.50.suspended': ['Kulüp askıya alındı.', 'Club suspended.'], 'tst.50.activated': ['Kulüp yeniden etkinleştirildi.', 'Club reactivated.'],
    'tst.51': ['İçerik kaldırıldı.', 'Content removed.'], 'tst.52.suspended': ['Kullanıcı askıya alındı.', 'User suspended.'], 'tst.52.unsuspended': ['Kullanıcının askısı kaldırıldı.', 'User unsuspended.'], 'tst.53.pinned': ['Gönderi sabitlendi.', 'Post pinned.'], 'tst.53.unpinned': ['Sabitleme kaldırıldı.', 'Post unpinned.'], 'tst.54.opened': ['Başvurular açıldı.', 'Applications opened.'], 'tst.54.closed': ['Başvurular kapatıldı.', 'Applications closed.'], 'tst.55': ['Yeni bildirim: {title}', 'New notification: {title}'],
    'tst.56': ['Şikayet kapatıldı.', 'Report dismissed.'], 'tst.57': ['Fotoğraf güncellendi.', 'Photo updated.'], 'tst.58': ['Demo: {what} açılıyor.', 'Demo: opening {what}.'],
    'tst.x1': ['Bu kulüp şu an başvuru almıyor.', 'This club is not accepting applications right now.'], 'tst.x2': ['Bu etkinliğin kayıtları kapalı.', 'Registration for this event is closed.'], 'tst.x3': ['Tekrar göndermek için {s} sn bekle.', 'Wait {s}s to resend.'], 'tst.x4': ['{date} tarihine kadar tekrar başvuramazsın.', 'You cannot reapply until {date}.'], 'tst.x5': ['En fazla 4 görsel ekleyebilirsin.', 'You can add at most 4 photos.'], 'tst.x6': ['Bu etkinlik sona erdi.', 'This event has ended.'], 'tst.x7': ['Hatırlatıcı için önce etkinliğe katıl.', 'Join the event to set a reminder.'], 'tst.x8': ['{count} kişi katılıyor.', '{count} people are going.'],
    'tst.x9': ['Kaydedilecek değişiklik yok.', 'No changes to save.'], 'tst.x10': ['Önce başkanlığı devretmelisin.', 'Transfer the presidency first.'], 'tst.x11': ['Şifreni gir ve onaylamak için SİL yaz.', 'Enter your password and type SİL to confirm.'], 'tst.x12': ['Yoklama alınacak etkinlik yok.', 'No event to take attendance for.'], 'tst.x13': ['{name} kayıtlıya alındı.', '{name} was promoted from the waitlist.'], 'tst.x14': ['Kontenjan dolu; önce yer açılmalı.', 'The event is full; a spot must open first.'], 'tst.x15.opened': ['Kayıtlar açıldı.', 'Registration opened.'], 'tst.x15.closed': ['Kayıtlar kapatıldı.', 'Registration closed.'], 'tst.x16': ['Önce "Tümünü sessize al" seçeneğini kapat.', 'Turn off "Mute all" first.'],
    'tst.x17': ['Karar geri alındı; başvuru yeniden beklemede.', 'Decision undone; the application is pending again.'], 'tst.x18': ['Bu işlem için yetkin yok.', "You don't have permission for this."], 'tst.x19': ['Etkinlik taslağa alındı.', 'Event moved to drafts.'], 'tst.x20': ['Onaylamak için DEVRET yaz.', 'Type DEVRET to confirm.'], 'tst.x21': ['Bu hesabın bekleyen başvurusu yok.', 'This account has no pending application.'], 'tst.x22': ['Önce bir hesapla giriş yap.', 'Sign in with an account first.'], 'tst.x23': ['Demo verisi sıfırlandı.', 'Demo data was reset.'],
    /* notification templates */
    'notifType.application_received.title': ['Yeni başvuru', 'New application'], 'notifType.application_received.body': ['{user}, {club} kulübüne katılmak için başvurdu.', '{user} applied to join {club}.'],
    'notifType.application_approved.title': ['Başvurun onaylandı', 'Application approved'], 'notifType.application_approved.body': ['{club} üyeliğin onaylandı. Hoş geldin!', 'Your {club} membership was approved. Welcome!'],
    'notifType.application_rejected.title': ['Başvurun reddedildi', 'Application rejected'], 'notifType.application_rejected.body': ['{club} başvurun bu kez kabul edilmedi. Nedeni görmek için dokun.', 'Your {club} application was not accepted this time. Tap to see why.'],
    'notifType.removed_from_club.title': ['Üyelik sona erdi', 'Membership ended'], 'notifType.removed_from_club.body': ['{club} üyeliğin kulüp yönetimi tarafından sonlandırıldı.', 'Your {club} membership was ended by the board.'],
    'notifType.role_changed.title': ['Rolün değişti', 'Your role changed'], 'notifType.role_changed.body': ['{club} kulübünde yeni rolün: {role}.', 'Your new role in {club}: {role}.'],
